import{_ as e,o as t,c as r,a2 as n}from"./chunks/framework.DfDAiEgj.js";const m=JSON.parse('{"title":"推荐系统","description":"","frontmatter":{},"headers":[],"relativePath":"ai-dive/recommand.md","filePath":"ai-dive/recommand.md","lastUpdated":null}'),l={name:"ai-dive/recommand.md"};function i(o,a,h,p,s,c){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="推荐系统" tabindex="-1">推荐系统 <a class="header-anchor" href="#推荐系统" aria-label="Permalink to &quot;推荐系统&quot;">​</a></h1><p>不是让阿尔法狗下棋，也不是siri语音操控，更不是视频图像识别抓小偷，而是推荐算法最赚钱…</p><p>Facebook靠feed流插入广告推荐的算法，一年赚将近一千万美元</p><p>亚马逊、淘宝靠相关商品推荐，一年赚2000万美元…</p><p>今日头条、抖音、快手等短视频或B站长视频平台的崛起，也都是利用内容推荐算法，让大家爱不释手、欲罢不能…</p><p>上述产品统统搭建了属于自己的推荐系统，目前最赚钱的AI算法——推荐算法</p><p>有效的推荐算法，要解决三个问题</p><ol><li>相似主题推荐</li><li>海量标签处理</li><li>避免重复推荐</li></ol><p>相应的，为了解决实际应用场景中的上述三个问题，会有如下三个解决思路：</p><ol><li>立体几何的余弦相似度</li><li>Embedding向量化</li><li>预测点击率的优化策略 <a href="https://zhuanlan.zhihu.com/p/402289596" target="_blank" rel="noreferrer">^1</a></li></ol><h2 id="需求大" tabindex="-1">需求大 <a class="header-anchor" href="#需求大" aria-label="Permalink to &quot;需求大&quot;">​</a></h2><p>从企业的需求量来看，推荐 &gt; 搜索 &gt;= nlp &gt; cv，我想，题主也是想问，哪个垂直领域的工资平均水平最高，对于校招生，刚入职时没太多差别，但随着时间的发展，业务多、需求量大的方向优势就体现出来了，推荐领域的人才，由于业务场景多、需求大，容易拿到成绩，升职速度会快于同时期入职的其他方向的同学，工资自然就超过了。<a href="https://bbs.cvmart.net/articles/4932" target="_blank" rel="noreferrer">^2</a></p><p>Youtube 多目标排序+解决position bias（Recsys2019） - 魔法学院的Chilia的文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/405185215" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/405185215</a></p><p>Youtube 排序系统：Recommending What Video to Watch Next - 魔鬼吊儿郎的文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/82584437" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/82584437</a></p><h2 id="新方向" tabindex="-1">新方向 <a class="header-anchor" href="#新方向" aria-label="Permalink to &quot;新方向&quot;">​</a></h2><p>CRSLab：可能是最适合你的对话推荐系统开源库 - Francis Lancelot的文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/341955912" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/341955912</a></p>',16)])])}const u=e(l,[["render",i]]);export{m as __pageData,u as default};
